// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
  Img,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type AIAppExplainerProps = Record<string, any>;

const AIAppExplainer: React.FC<AIAppExplainerProps> = ({
  backgroundColor = "#0b0c10",
  transparentBackground = false,
  durationInSeconds = 8,
  accentColor = "#45f3ff",
  titleText = "Most AI Apps Are Built on Foundation Models",
  foundationNodes = ["OpenAI", "ChatGPT", "Large Language Models"],
  imageUpload1 = "",
  imageUpload2 = "",
  imageUpload3 = "",
  imageUpload4 = "",
  finalText = "Many AI tools are wrappers built on foundation models.",
}) => {
  useFontLoader(["Space Grotesk"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  const imageUploads = [imageUpload1, imageUpload2, imageUpload3, imageUpload4];

  // Global Y Layout Map (relative to scrolling container)
  const Y_TITLE1 = 150;
  const Y_NODES = 600;
  const Y_JUNC = 850;
  const Y_CARDS = 1100;
  const Y_TITLE2 = 2150;

  // Card Grid Layout
  const cardWidth = width * 0.35;
  const cardHeight = height * 0.25;
  const cardGap = 40;
  
  // Card Centers (X)
  const col1X = width / 2 - cardWidth / 2 - cardGap / 2;
  const col2X = width / 2 + cardWidth / 2 + cardGap / 2;
  
  // Card Tops (Y)
  const row1Y = Y_CARDS;
  const row2Y = Y_CARDS + cardHeight + cardGap;

  // Node Centers (X)
  const nodeCenters = [width * 0.2, width * 0.5, width * 0.8];

  // --- Scroll Animation ---
  const maxScroll = -(Y_TITLE2 - height + 300);
  const scrollY = interpolate(frame, [110, 230], [0, maxScroll], {
    easing: Easing.inOut(Easing.cubic),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // --- Particle Background ---
  const particles = React.useMemo(() => {
    return Array.from({ length: 40 }).map((_, i) => ({
      x: (i * 87) % width,
      y: (i * 143) % height,
      size: (i % 3) + 1,
      speed: (i % 5) * 0.5 + 0.2,
      delay: (i * 7) % 100,
    }));
  }, [width, height]);

  // --- Line Animation Progress ---
  const topPathProgress = interpolate(frame, [40, 60], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const upperLineProgress = interpolate(frame, [70, 100], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const lowerLineProgress = interpolate(frame, [100, 130], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // --- Helper Components inline for parser safety ---

  const renderParticles = () => (
    <AbsoluteFill style={{ overflow: "hidden" }}>
      {particles.map((p, i) => {
        const pY = p.y - (frame * p.speed) % height;
        const opacity = interpolate(
          Math.sin((frame - p.delay) * 0.05),
          [-1, 1],
          [0.1, 0.6]
        );
        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: p.x,
              top: pY < -10 ? height + pY : pY,
              width: p.size,
              height: p.size,
              backgroundColor: accentColor,
              borderRadius: "50%",
              opacity,
              boxShadow: `0 0 10px ${accentColor}`,
              transition: "none",
            }}
          />
        );
      })}
    </AbsoluteFill>
  );

  const renderGridLines = () => (
    <svg style={{ position: "absolute", width: "100%", height: "100%", transition: "none" }}>
      <defs>
        <pattern id="grid" width="80" height="80" patternUnits="userSpaceOnUse">
          <path
            d="M 80 0 L 0 0 0 80"
            fill="none"
            stroke="rgba(255,255,255,0.03)"
            strokeWidth="1"
            style={{ transition: "none" }}
          />
        </pattern>
      </defs>
      <rect width="100%" height="100%" fill="url(#grid)" style={{ transition: "none" }} />
      {/* Vignette Overlay */}
      <rect
        width="100%"
        height="100%"
        fill="url(#vignette)"
        style={{ transition: "none" }}
      />
      <defs>
        <radialGradient id="vignette">
          <stop offset="50%" stopColor="transparent" />
          <stop offset="100%" stopColor={bgColor} />
        </radialGradient>
      </defs>
    </svg>
  );

  const renderSVGConnections = () => {
    const titleBottomY = Y_TITLE1 + 150;
    const nodeTopY = Y_NODES - 60;
    const nodeBottomY = Y_NODES + 60;

    // Paths from Title to Nodes
    const topPaths = [
      `M ${width / 2} ${titleBottomY} C ${width / 2} ${titleBottomY + 100}, ${nodeCenters[0]} ${nodeTopY - 100}, ${nodeCenters[0]} ${nodeTopY}`,
      `M ${width / 2} ${titleBottomY} L ${width / 2} ${nodeTopY}`,
      `M ${width / 2} ${titleBottomY} C ${width / 2} ${titleBottomY + 100}, ${nodeCenters[2]} ${nodeTopY - 100}, ${nodeCenters[2]} ${nodeTopY}`,
    ];
    
    // Paths from Nodes to Junction Point
    const upperPaths = [
      `M ${nodeCenters[0]} ${nodeBottomY} C ${nodeCenters[0]} ${Y_JUNC - 100}, ${width / 2} ${Y_JUNC - 100}, ${width / 2} ${Y_JUNC}`,
      `M ${nodeCenters[1]} ${nodeBottomY} L ${width / 2} ${Y_JUNC}`,
      `M ${nodeCenters[2]} ${nodeBottomY} C ${nodeCenters[2]} ${Y_JUNC - 100}, ${width / 2} ${Y_JUNC - 100}, ${width / 2} ${Y_JUNC}`,
    ];

    // Paths from Junction to Cards
    const lowerPaths = [
      `M ${width / 2} ${Y_JUNC} C ${width / 2} ${Y_JUNC + 100}, ${col1X} ${Y_JUNC + 100}, ${col1X} ${row1Y}`,
      `M ${width / 2} ${Y_JUNC} C ${width / 2} ${Y_JUNC + 100}, ${col2X} ${Y_JUNC + 100}, ${col2X} ${row1Y}`,
      `M ${width / 2} ${Y_JUNC} C ${width / 2} ${Y_JUNC + 300}, ${col1X} ${Y_JUNC + 300}, ${col1X} ${row2Y}`,
      `M ${width / 2} ${Y_JUNC} C ${width / 2} ${Y_JUNC + 300}, ${col2X} ${Y_JUNC + 300}, ${col2X} ${row2Y}`,
    ];

    return (
      <svg
        style={{
          position: "absolute",
          width: "100%",
          height: height * 3,
          pointerEvents: "none",
          transition: "none",
        }}
      >
        {topPaths.map((d, i) => (
          <path
            key={`top-${i}`}
            d={d}
            fill="none"
            stroke={accentColor}
            strokeWidth="3"
            strokeLinecap="round"
            pathLength="100"
            strokeDasharray="100"
            strokeDashoffset={100 - topPathProgress * 100}
            style={{
              transition: "none",
              filter: `drop-shadow(0 0 15px ${accentColor}80)`,
            }}
          />
        ))}
        {upperPaths.map((d, i) => (
          <path
            key={`up-${i}`}
            d={d}
            fill="none"
            stroke={accentColor}
            strokeWidth="3"
            strokeLinecap="round"
            pathLength="100"
            strokeDasharray="100"
            strokeDashoffset={100 - upperLineProgress * 100}
            style={{
              transition: "none",
              filter: `drop-shadow(0 0 15px ${accentColor}80)`,
            }}
          />
        ))}
        {lowerPaths.map((d, i) => (
          <path
            key={`low-${i}`}
            d={d}
            fill="none"
            stroke={accentColor}
            strokeWidth="3"
            strokeLinecap="round"
            pathLength="100"
            strokeDasharray="100"
            strokeDashoffset={100 - lowerLineProgress * 100}
            style={{
              transition: "none",
              filter: `drop-shadow(0 0 15px ${accentColor}80)`,
            }}
          />
        ))}
      </svg>
    );
  };

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Space Grotesk, sans-serif",
      }}
    >
      {renderGridLines()}
      {renderParticles()}

      {/* Scrolling Container */}
      <AbsoluteFill
        style={{
          transform: `translateY(${scrollY}px)`,
          transition: "none",
        }}
      >
        {renderSVGConnections()}

        {/* Title 1 */}
        {(() => {
          const t1Op = interpolate(frame, [10, 30], [0, 1], { extrapolateRight: "clamp" });
          const t1Y = interpolate(frame, [10, 30], [50, 0], { extrapolateRight: "clamp" });
          return (
            <div
              style={{
                position: "absolute",
                top: Y_TITLE1,
                width: "100%",
                textAlign: "center",
                opacity: t1Op,
                transform: `translateY(${t1Y}px)`,
                transition: "none",
                color: "white",
                fontSize: 64,
                fontWeight: "bold",
                textShadow: `0 0 30px ${accentColor}80`,
                padding: "0 100px",
              }}
            >
              {titleText}
            </div>
          );
        })()}

        {/* Foundation Nodes */}
        {foundationNodes.slice(0, 3).map((label, i) => {
          const delay = 50 + i * 15;
          const scale = spring({
            fps,
            frame: frame - delay,
            config: { damping: 14, stiffness: 100 },
          });
          const op = interpolate(frame - delay, [0, 15], [0, 1], { extrapolateRight: "clamp" });

          return (
            <div
              key={i}
              style={{
                position: "absolute",
                top: Y_NODES - 60, // center vertically
                left: nodeCenters[i] - 150, // width is 300, center horizontally
                width: 300,
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                transform: `scale(${scale})`,
                opacity: op,
                transition: "none",
              }}
            >
              <div
                style={{
                  width: 120,
                  height: 120,
                  borderRadius: 60,
                  border: `3px solid ${accentColor}`,
                  backgroundColor: "rgba(0, 0, 0, 0.6)",
                  boxShadow: `0 0 40px ${accentColor}60`,
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                  transition: "none",
                }}
              >
                <div
                  style={{
                    width: 40,
                    height: 40,
                    borderRadius: 20,
                    backgroundColor: accentColor,
                    boxShadow: `0 0 20px ${accentColor}`,
                    transition: "none",
                  }}
                />
              </div>
              <div
                style={{
                  marginTop: 30,
                  color: "white",
                  fontSize: 28,
                  fontWeight: 600,
                  textAlign: "center",
                  lineHeight: 1.2,
                  textShadow: "0 2px 10px rgba(0,0,0,0.8)",
                  transition: "none",
                }}
              >
                {label}
              </div>
            </div>
          );
        })}

        {/* 4 Image Upload Frames */}
        {Array.from({ length: 4 }).map((_, i) => {
          const delay = 130 + i * 15;
          const op = interpolate(frame - delay, [0, 20], [0, 1], { extrapolateRight: "clamp" });
          const yOff = interpolate(frame - delay, [0, 20], [60, 0], { extrapolateRight: "clamp" });
          
          const isLeft = i % 2 === 0;
          const isTop = i < 2;
          
          const posX = isLeft ? col1X : col2X;
          const posY = isTop ? row1Y : row2Y;
          const imageSrc = imageUploads[i] || "";

          return (
            <div
              key={i}
              style={{
                position: "absolute",
                left: posX - cardWidth / 2,
                top: posY,
                width: cardWidth,
                height: cardHeight,
                opacity: op,
                transform: `translateY(${yOff}px)`,
                borderRadius: 30,
                border: `2px solid ${accentColor}60`,
                backgroundColor: "rgba(255, 255, 255, 0.03)",
                backdropFilter: "blur(12px)",
                boxShadow: `0 20px 50px rgba(0,0,0,0.8), inset 0 0 30px ${accentColor}20`,
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
                flexDirection: "column",
                overflow: "hidden",
                transition: "none",
              }}
            >
              {imageSrc ? (
                <Img
                  src={imageSrc}
                  style={{ width: "100%", height: "100%", objectFit: "cover", transition: "none" }}
                />
              ) : (
                <>
                  <div
                    style={{
                      width: 60,
                      height: 60,
                      borderRadius: 15,
                      border: `3px dashed ${accentColor}80`,
                      marginBottom: 20,
                      transition: "none",
                    }}
                  />
                  <h3
                    style={{
                      color: accentColor,
                      fontSize: 24,
                      letterSpacing: 2,
                      opacity: 0.8,
                      margin: 0,
                      transition: "none",
                    }}
                  >
                    IMAGE UPLOAD {i + 1}
                  </h3>
                </>
              )}
            </div>
          );
        })}

        {/* Final Text */}
        {(() => {
          const t2Op = interpolate(frame, [200, 220], [0, 1], { extrapolateRight: "clamp" });
          const t2Y = interpolate(frame, [200, 220], [50, 0], { extrapolateRight: "clamp" });
          return (
            <div
              style={{
                position: "absolute",
                top: Y_TITLE2,
                width: "100%",
                textAlign: "center",
                opacity: t2Op,
                transform: `translateY(${t2Y}px)`,
                transition: "none",
                color: "rgba(255,255,255,0.7)",
                fontSize: 48,
                fontWeight: 400,
                padding: "0 100px",
              }}
            >
              {finalText}
            </div>
          );
        })()}
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default AIAppExplainer;